// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/// Maximum retry attempts for the compaction LLM call (Level 4 backoff and
/// Level 3 drop-oldest fallback).
const MAX_COMPACTION_RETRY_ATTEMPTS: u32 = 5;

/// Default maximum completion tokens for the compaction LLM call.
///
/// TODO: use in compaction round to enforce a max output size on the
/// summarization LLM call. Currently unused but kept here so the value is
/// documented and ready when the `max_output_size` field on
/// [`CompactionRoundInput`] is wired up.
#[allow(dead_code)]
const DEFAULT_COMPACTION_MAX_COMPLETION_TOKENS: u64 = 128 * 1024; // 131072

/// Safety ratio applied when learning the max context from an overflow error.
/// The observed max is `estimated_tokens * OVERFLOW_CONTEXT_SAFETY_RATIO`
/// (rounded down), so we stay safely below the true limit — the failed
/// request already exceeded the limit, so any value at or above it is an
/// overestimate.
const OVERFLOW_CONTEXT_SAFETY_RATIO: f64 = 0.85;

/// Ratio of the observed max context at which compaction is considered
/// recovered (consecutive overflow counter resets).
const OVERFLOW_STATUS_RECOVERY_RATIO: f64 = 0.5;

/// Maximum overflow-triggered shrink attempts before giving up.
const MAX_COMPACTION_OVERFLOW_SHRINK_ATTEMPTS: u32 = 3;

/// Token-budget ratios for each overflow shrink attempt. The first attempt
/// keeps 70% of the history, the second 50%, the third 35%.
const COMPACTION_OVERFLOW_SHRINK_RATIOS: [f64; 3] = [0.7, 0.5, 0.35];

/// The prefix prepended to every compaction summary. Tells the model that the
/// conversation was compacted and how to interpret the summary.
const COMPACTION_SUMMARY_PREFIX: &str = "The conversation so far has been compacted to free up context. What follows is your own working summary of this task — use it to continue your train of thought rather than starting over. Treat it as notes, not proof: where it says a step was done, tests passed, or a fix worked, verify that yourself before relying on it. Any user messages earlier in this context are preserved verbatim from the compacted conversation; where a system-reminder note among them marks an omitted middle section, the user messages it replaced are covered by this summary. Entry numbers cited in this summary (e.g. \"entries #60-#70\") are stable across compactions and may be referenced in later notes.";

// ---------------------------------------------------------------------------
// CompactionStrategy
// ---------------------------------------------------------------------------

/// Configuration for compaction behavior.
///
/// Controls when compaction triggers (ratio of max context tokens), how much
/// context is reserved, and limits on compaction frequency.
#[derive(Debug, Clone)]
pub struct CompactionStrategy {
    /// Ratio of max context tokens at which to trigger compaction (0.85 = 85%).
    pub trigger_ratio: f64,
    /// Ratio at which to block and wait for compaction (0.85).
    pub block_ratio: f64,
    /// Reserved context size in tokens (50000). When the remaining context
    /// falls below this, compaction triggers regardless of the ratio.
    pub reserved_context_size: u64,
    /// Maximum compactions per turn (`u32::MAX` = no limit).
    pub max_compaction_per_turn: u32,
    /// Maximum overflow compaction attempts (3).
    pub max_overflow_compaction_attempts: u32,
    /// Maximum number of messages allowed in the canonical history before
    /// further appends are rejected (10000 by default). Guards against
    /// runaway tool exchanges growing memory without bound before
    /// compaction triggers.
    pub max_history_messages: usize,
    /// Maximum number of messages buffered while a tool exchange is open
    /// before further buffering is rejected (1000 by default).
    pub max_deferred_messages: usize,
    /// Maximum context tokens for this model. 0 = unknown (no ratio-based
    /// triggering).
    pub max_context_tokens: u64,
    /// Retention-tail budget as a window ratio (default 0.16, ADR-001).
    /// Ignored when `retention_tail_tokens` is set (US6.2 mutual exclusion).
    pub retention_tail_ratio: f64,
    /// Absolute retention-tail budget in tokens; overrides the ratio when
    /// set.
    pub retention_tail_tokens: Option<u64>,
}

impl Default for CompactionStrategy {
    fn default() -> Self {
        Self {
            trigger_ratio: 0.85,
            block_ratio: 0.85,
            reserved_context_size: 50_000,
            max_compaction_per_turn: u32::MAX, // Infinity
            max_overflow_compaction_attempts: 3,
            max_history_messages: DEFAULT_MAX_HISTORY_MESSAGES,
            max_deferred_messages: DEFAULT_MAX_DEFERRED_MESSAGES,
            max_context_tokens: 0, // 0 = unknown, no ratio-based triggering
            retention_tail_ratio: retention::RETENTION_TAIL_RATIO,
            retention_tail_tokens: None,
        }
    }
}

impl CompactionStrategy {
    /// Whether the used token count warrants compaction.
    ///
    /// Returns `true` if the used tokens exceed the trigger ratio of the max
    /// context, or if the remaining context falls below the reserved size.
    pub fn should_compact(&self, used_tokens: u64) -> bool {
        if self.max_context_tokens == 0 {
            return false;
        }
        used_tokens >= (self.max_context_tokens as f64 * self.trigger_ratio) as u64
            || self.should_use_reserved_context(used_tokens)
    }

    /// Whether the used token count warrants blocking.
    ///
    /// Returns `true` if the used tokens exceed the block ratio of the max
    /// context, or if the remaining context falls below the reserved size.
    pub fn should_block(&self, used_tokens: u64) -> bool {
        if self.max_context_tokens == 0 {
            return false;
        }
        used_tokens >= (self.max_context_tokens as f64 * self.block_ratio) as u64
            || self.should_use_reserved_context(used_tokens)
    }

    /// Whether the remaining context is below the reserved size.
    fn should_use_reserved_context(&self, used_tokens: u64) -> bool {
        self.reserved_context_size > 0
            && self.reserved_context_size < self.max_context_tokens
            && used_tokens + self.reserved_context_size >= self.max_context_tokens
    }
}

// ---------------------------------------------------------------------------
// CompactionSource
// ---------------------------------------------------------------------------

/// Derive the ADR-007 provenance interval from the live re-cut's replaced
/// prefix: the minimum/maximum `entry_seq` of `live_history[..tail_start]`.
///
/// The range is a *bracket*, not a contiguous run: an undo between the
/// prefix's materializations leaves its removed numbers inside the bracket
/// (numbering never rewinds, ADR-007), and the fold uses exactly that to
/// re-derive the live counter on replay. An empty prefix yields `(None,
/// None)` — nothing was replaced, so the wire op omits the fields.
fn replaced_entry_range(
    live_history: &[ContextMessage],
    tail_start: usize,
) -> (Option<u64>, Option<u64>) {
    // Stamped-0 sentinel invariant (ADR-007, Task 2 review): `entry_seq == 0`
    // means BOTH "unassigned" and "the session's very first entry". The two
    // readings coincide only because a stamped-0 record can never replay at
    // a nonzero counter (live `push_history` reassigns any 0 it sees, and
    // the fold replays the session's first entry where the counter is also
    // 0). If a stamped-0 record COULD replay at a nonzero counter, the
    // min/max below would silently pick 0 for a prefix whose true minimum
    // is higher — and the replay-side bracket correction would drift with
    // no error anywhere. The assert pins the live half of that invariant:
    // a 0 may only ever sit at the head of the history.
    debug_assert!(
        !live_history
            .iter()
            .enumerate()
            .any(|(index, msg)| msg.entry_seq == 0 && index > 0),
        "stamped-0 sentinel break: entry_seq == 0 may only be the history's first entry"
    );
    let prefix = live_history.get(..tail_start).unwrap_or(live_history);
    (
        prefix.iter().map(|msg| msg.entry_seq).min(),
        prefix.iter().map(|msg| msg.entry_seq).max(),
    )
}

/// Map a [`CompactionResult`]'s ADR-007 provenance onto the wire apply op's
/// field triple (`firstReplacedEntrySeq`, `lastReplacedEntrySeq`,
/// `droppedEntrySeqs`).
///
/// Every production write point that persists a
/// `WireOp::ContextApplyCompaction` — the turn_flow overflow-recovery block
/// path, the auto-compaction hooks path, the embedded manual-compaction
/// handler, and the test-side resume replay — derives its fields through
/// this helper, so the mapping exists exactly once. A first↔last swap
/// anywhere compiles silently (both ends are symmetric `Option<u64>`s);
/// centralizing the mapping is what keeps `first <= last` (the range is the
/// replaced prefix's min/max entry number, see ADR-007) wired correctly.
///
/// Wire-shape rules (ADR-007, mirrored by `WireOp::ContextApplyCompaction`'s
/// serde attributes): both range ends are optional and stay absent when the
/// apply never materialized a replaced prefix, and an EMPTY dropped list
/// must also stay absent — never an empty array.
pub fn apply_compaction_op_fields(
    result: &CompactionResult,
) -> (Option<u64>, Option<u64>, Option<Vec<u64>>) {
    (
        result.first_replaced_entry_seq,
        result.last_replaced_entry_seq,
        (!result.dropped_entry_seqs.is_empty()).then(|| result.dropped_entry_seqs.clone()),
    )
}

/// What triggered the compaction.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum CompactionSource {
    /// Automatically triggered by token-count threshold.
    Auto,
    /// Manually triggered by the user or host.
    Manual,
}

// ---------------------------------------------------------------------------
// CompactionResult
// ---------------------------------------------------------------------------

/// Result of a compaction round.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CompactionResult {
    /// The raw summary text from the LLM summarizer.
    pub summary: String,
    /// The context summary text (prefixed with the compaction handoff marker).
    pub context_summary: String,
    /// Number of messages that were compacted (original history length).
    pub compacted_count: usize,
    /// Token count before compaction.
    pub tokens_before: u64,
    /// Token count after compaction.
    pub tokens_after: u64,
    /// Number of messages dropped during overflow recovery.
    pub dropped_count: usize,
    /// Indices (ascending) into the old segment of the messages dropped by
    /// the overflow-recovery ladder (Levels 2 and 3) — entries that were
    /// never even covered by the summary input (ADR-007's
    /// "not recoverable from this note" boundary).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub dropped_entry_positions: Vec<usize>,
    /// Entry numbers (ADR-007 `entry_seq`) of the entries dropped by the
    /// overflow-recovery ladder — mapped from
    /// [`Self::dropped_entry_positions`] through the old segment's entry
    /// seqs (by position, never by `dropped_count`: the count includes
    /// hook-context slots the positions skip). Populated in `begin`'s
    /// round closure where the old segment is in scope.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub dropped_entry_seqs: Vec<u64>,
    /// ADR-007: the replaced prefix's entry-number range (closed interval)
    /// — the minimum/maximum `entry_seq` of `live_history
    /// [..tail_start]` at the apply. A bracket, not a contiguous run (an
    /// undo between the ends leaves its removed numbers inside). `None`
    /// when the apply was refused or the prefix was empty.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub first_replaced_entry_seq: Option<u64>,
    /// ADR-007: the replaced range's upper end (see
    /// [`Self::first_replaced_entry_seq`]).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_replaced_entry_seq: Option<u64>,
    /// Whether the result was actually applied to memory. A summary that
    /// fails the shrink check (变小校验 — the rewritten history must be
    /// smaller than the original) is rejected: the original history is kept
    /// and the flag reports the rejection to callers (wire-recording sites
    /// must not persist an apply op that never happened).
    pub applied: bool,
    /// Materialized memory slots kept verbatim as the retention tail
    /// (ADR-005 — persisted on the wire op for resume reconstruction).
    #[serde(default)]
    pub retained_tail_count: usize,
    /// Real user messages kept verbatim as the head essence.
    #[serde(default)]
    pub kept_head_user_message_count: usize,
    /// The elision marker exactly as inserted (serialized), `None` when
    /// nothing was omitted between head and summary.
    #[serde(default)]
    pub elision_message: Option<serde_json::Value>,
}

// ---------------------------------------------------------------------------
// ActiveCompaction
// ---------------------------------------------------------------------------

/// State of an in-flight background compaction.
struct ActiveCompaction {
    /// Cancel token for the background task.
    #[allow(dead_code)]
    cancel: CancelToken,
    /// The background task producing a `CompactionResult`.
    task: tokio::task::JoinHandle<EngineResult<CompactionResult>>,
}

/// The cancel registration of an in-flight manual compaction, tagged with
/// the attempt's identity — every later settle of the registration must
/// carry the same id, so a stale attempt can never clear a newer one's.
struct ManualAttempt {
    id: u64,
    cancel: CancelToken,
}

/// A handed-off manual compaction attempt: the background task plus the
/// cancellation channel and identity needed to settle the orchestrator's
/// registration when the attempt completes, fails, or is discarded.
#[derive(Debug)]
pub struct ManualCompactionHandle {
    /// The background summarizer round.
    pub task: tokio::task::JoinHandle<EngineResult<CompactionResult>>,
    /// The attempt's cancellation channel.
    pub cancel: CancelToken,
    /// The attempt's identity in the orchestrator's registration.
    pub attempt_id: u64,
}

// ---------------------------------------------------------------------------
// CompactionBeginParams
// ---------------------------------------------------------------------------

/// Parameters needed to start a background compaction via [`FullCompaction::begin`].
#[derive(Clone)]
pub struct CompactionBeginParams {
    /// The LLM adapter (wrapped in `Arc` for the background task).
    pub llm: Arc<dyn Llm>,
    /// Cancel token for the compaction.
    pub cancel: CancelToken,
    /// Optional custom instruction appended to the compaction prompt.
    pub custom_instruction: Option<String>,
    /// Optional max output size for the compaction LLM call.
    pub max_output_size: Option<u64>,
    /// Messages collected from PreCompact hooks' `additionalContext` output
    /// that the summarizer must see in addition to the history being
    /// compacted (TS parity: `injectHookAdditionalContext` before the round
    /// snapshots the history). They ride on the request only — they never
    /// land in session memory.
    pub hook_additional_context: Vec<ContextMessage>,
}

/// Build the summarizer-side messages for a PreCompact hook result's
/// `additionalContext`.
///
/// The hook engine merges every passing hook's `additionalContext` into one
/// newline-joined string; a single user message carrying it (origin
/// `hook_additional_context`) is the request-side shape. An empty or
/// whitespace-only value yields no message.
pub fn hook_additional_context_messages(additional_context: &str) -> Vec<ContextMessage> {
    if additional_context.trim().is_empty() {
        return Vec::new();
    }
    vec![
        ContextMessage::from_message(Message::user(additional_context))
            .with_origin(PromptOrigin::HookAdditionalContext),
    ]
}

/// Wait until no manual compaction is in flight.
///
/// TS parity (`promptService.startNext` deferral): a prompt arriving while a
/// manual compaction runs must not start its turn — the compaction's apply
/// rebuilds memory from the history snapshot taken at `begin`, so a turn
/// appending during the window would be clobbered by the apply. Turns call
/// this before their first mutation; the re-check loop makes the
/// subscribe-then-check ordering race-free (a settle that fires between the
/// initial check and the wait is still observed through the watch value).
pub async fn wait_manual_compaction_settle(compaction: &Arc<Mutex<FullCompaction>>) {
    let mut rx = {
        let comp = compaction.lock().unwrap_or_else(|e| e.into_inner());
        if !comp.manual_in_flight() {
            return;
        }
        comp.subscribe_settle()
    };
    loop {
        if rx.changed().await.is_err() {
            return;
        }
        if !compaction
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .manual_in_flight()
        {
            return;
        }
    }
}

// ---------------------------------------------------------------------------
// FullCompaction
// ---------------------------------------------------------------------------

/// The compaction orchestrator.
///
/// Manages compaction state per session: tracks how many compactions have
/// occurred in the current turn, whether a background compaction is in flight,
/// and the observed max context tokens (learned from overflow errors).
///
/// ## Lifecycle
///
/// 1. At the start of each turn, call [`reset_for_turn`].
/// 2. Before each LLM step, call [`check_auto_compaction`] to see if
///    compaction should fire.
/// 3. If compaction is needed, call [`begin`] to start it in the background,
///    then [`block`] to wait for it and apply the result.
/// 4. On overflow errors, call [`handle_overflow_error`] for recovery.
///
/// [`reset_for_turn`]: FullCompaction::reset_for_turn
/// [`check_auto_compaction`]: FullCompaction::check_auto_compaction
/// [`begin`]: FullCompaction::begin
/// [`block`]: FullCompaction::block
/// [`handle_overflow_error`]: FullCompaction::handle_overflow_error
pub struct FullCompaction {
    /// Compaction strategy configuration.
    strategy: CompactionStrategy,
    /// Count of compactions in the current turn.
    compaction_count_in_turn: u32,
    /// Token count baseline after last compaction (to skip redundant
    /// re-compaction when nothing new has been added).
    last_compacted_token_count: Option<u64>,
    /// Consecutive overflow-triggered compactions.
    consecutive_overflow_compactions: u32,
    /// In-flight compaction task (None if idle).
    active: Option<ActiveCompaction>,
    /// Cancel registration of an in-flight *manual* compaction, tagged
    /// with the attempt's identity. The task handle is handed to the
    /// caller of [`begin`](FullCompaction::begin) (the fire-and-forget
    /// apply task), so the token is the only way to stop a manual
    /// compaction once it is running — dropping a `JoinHandle` detaches
    /// rather than aborts. Set for `Manual`-source begins, cleared when
    /// the *owning* attempt settles (a stale attempt must never clear a
    /// newer one's registration).
    manual_cancel: Option<ManualAttempt>,
    /// Identity of the next manual attempt (monotonic per orchestrator).
    next_manual_attempt_id: u64,
    /// Observed max context tokens (learned from overflow errors).
    observed_max_context_tokens: Option<u64>,
    /// Settle signal for [`wait_manual_compaction_settle`] — bumped on every
    /// [`settle_manual`](Self::settle_manual) so a turn parked in the buffer
    /// phase wakes as soon as no manual compaction is in flight anymore.
    settle_tx: tokio::sync::watch::Sender<u64>,
    settle_count: u64,
    /// Begin-time history snapshot of the in-flight attempt (SDR-011,
    /// architecture §5.4 并发变化检查): the exact prefix the summarizer was
    /// asked to summarize. Consumed by the apply seams (`block` /
    /// `apply_compaction_result`) for the prefix-race check — the live
    /// history must still be the snapshot plus, at most, appended real user
    /// input; any other divergence cancels the round (memory untouched, no
    /// apply record on the wire, orchestrator free again).
    pending_snapshot: Option<Vec<ContextMessage>>,
}

impl std::fmt::Debug for FullCompaction {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("FullCompaction")
            .field("strategy", &self.strategy)
            .field("compaction_count_in_turn", &self.compaction_count_in_turn)
            .field(
                "last_compacted_token_count",
                &self.last_compacted_token_count,
            )
            .field(
                "consecutive_overflow_compactions",
                &self.consecutive_overflow_compactions,
            )
            .field("is_compacting", &self.is_compacting())
            .field(
                "observed_max_context_tokens",
                &self.observed_max_context_tokens,
            )
            .finish()
    }
}

impl FullCompaction {
    /// Create a new compaction orchestrator with the given strategy.
    pub fn new(strategy: CompactionStrategy) -> Self {
        Self {
            strategy,
            compaction_count_in_turn: 0,
            last_compacted_token_count: None,
            consecutive_overflow_compactions: 0,
            active: None,
            manual_cancel: None,
            next_manual_attempt_id: 0,
            observed_max_context_tokens: None,
            settle_tx: tokio::sync::watch::channel(0).0,
            settle_count: 0,
            pending_snapshot: None,
        }
    }

    /// Reset per-turn state.
    ///
    /// Called at the start of each turn. Resets:
    /// - `compaction_count_in_turn` → 0
    /// - `last_compacted_token_count` → None
    /// - `consecutive_overflow_compactions` → 0
    pub fn reset_for_turn(&mut self) {
        self.compaction_count_in_turn = 0;
        self.last_compacted_token_count = None;
        self.consecutive_overflow_compactions = 0;
    }

    /// Check whether auto-compaction should fire.
    ///
    /// Returns `Ok(true)` if compaction should be triggered, `Ok(false)` if
    /// not. Returns `Err(ContextOverflow)` if `throw_on_limit` is true and
    /// the per-turn compaction limit has been exceeded.
    ///
    /// Conditions that skip compaction:
    /// - A compaction is already in flight.
    /// - The per-turn limit has been reached.
    /// - The token count is below the trigger threshold.
    /// - Nothing new has been added since the last compaction (token count
    ///   hasn't grown beyond the last post-compaction baseline).
    pub fn check_auto_compaction(
        &mut self,
        memory: &ContextMemory,
        throw_on_limit: bool,
    ) -> EngineResult<bool> {
        if self.is_compacting() {
            return Ok(false);
        }

        // Check per-turn limit.
        if self.compaction_count_in_turn >= self.strategy.max_compaction_per_turn {
            if throw_on_limit {
                return Err(EngineError::ContextOverflow {
                    attempts: self.compaction_count_in_turn,
                });
            }
            return Ok(false);
        }

        let used_tokens = memory.token_count_with_pending();

        // Check trigger threshold.
        if !self.strategy.should_compact(used_tokens) {
            return Ok(false);
        }

        // Prune-first (修剪优先于摘要, P8a-2): the normal projection no
        // longer micro-compacts (mutating the request prefix destroyed the
        // provider's prompt cache), so this re-measure currently equals the
        // raw estimate and falls through. It stays the seam where a future
        // gated, cache-aligned trim re-measures before a summarizer call —
        // pressure relieved by trimming would skip the summary.
        let pruned_tokens = memory.pruned_request_token_estimate();
        if !self.strategy.should_compact(pruned_tokens) {
            return Ok(false);
        }

        // Skip if nothing new since last compaction.
        if let Some(last) = self.last_compacted_token_count
            && used_tokens <= last
        {
            return Ok(false);
        }

        Ok(true)
    }

    /// Whether the turn should block and wait for an in-flight compaction.
    ///
    /// Returns `true` if a compaction is in flight, or if the token count
    /// exceeds the block ratio.
    pub fn should_block(&self, memory: &ContextMemory) -> bool {
        if self.is_compacting() {
            return true;
        }
        let used_tokens = memory.token_count_with_pending();
        self.strategy.should_block(used_tokens)
    }

    /// Start a background compaction.
    ///
    /// Spawns a tokio task that calls the LLM to generate a summary. The
    /// result is retrieved and applied via [`block`].
    ///
    /// If a compaction is already in flight, this is a no-op.
    ///
    /// [`block`]: FullCompaction::block
    pub fn begin(
        &mut self,
        source: CompactionSource,
        params: CompactionBeginParams,
        memory: &ContextMemory,
    ) -> EngineResult<()> {
        if self.is_compacting() {
            return Ok(());
        }
        // A manual compaction stays registered here after `begin` hands
        // its task to the caller — guard a second manual begin against
        // the one still in flight (`is_compacting` can no longer see it,
        // the handle lives with the caller's apply task).
        if matches!(source, CompactionSource::Manual) && self.manual_cancel.is_some() {
            return Err(EngineError::CompactionFailed(
                "a compaction is already in flight".to_string(),
            ));
        }

        // Check per-turn limit.
        if self.compaction_count_in_turn >= self.strategy.max_compaction_per_turn {
            return Err(EngineError::CompactionFailed(
                "max compaction per turn exceeded".to_string(),
            ));
        }

        // Snapshot history for the background task.
        let history: Vec<_> = memory.history().to_vec();
        let tokens_before = memory.token_count_with_pending();

        // Retention-tail cut (ADR-001) at the snapshot: the summarizer only
        // ever sees the OLD segment (`history[..cut.tail_start]`). No legal
        // cut → give up (US2.6: abort without writing anything — the
        // summarizer never starts). `CompactionUnable` (not `CompactionFailed`)
        // because this is a "nothing to compact" condition, not a failure:
        // the manual RPC renders it as an info-level skip (SDR-003).
        let retention_budget = self.retention_budget_tokens();
        let Some(cut) = retention::compute_retention_tail(&history, retention_budget) else {
            tracing::debug!(
                retention_budget,
                "compaction skipped: no legal retention-tail cut"
            );
            return Err(EngineError::CompactionUnable(
                "no legal retention-tail cut".to_string(),
            ));
        };
        let old_segment: Vec<ContextMessage> = history[..cut.tail_start].to_vec();
        let compacted_count = cut.tail_start;
        // ADR-007: the planned cut's replaced-range bracket — what the round
        // WAS asked to summarize. Threaded into the round so the summarizer
        // instruction can state the entry range. The apply path derives its
        // own bracket from the live re-cut; the two differ when real user
        // input lands between begin and apply, and that is correct — the
        // instruction describes the planned segment, the apply record what
        // was actually replaced.
        let planned_entry_range = replaced_entry_range(&history, cut.tail_start);

        let cancel_for_task = params.cancel.clone();
        let cancel = params.cancel.clone();
        let custom_instruction = params.custom_instruction.clone();
        let llm = params.llm.clone();
        let hook_additional_context = params.hook_additional_context.clone();

        let task = tokio::spawn(async move {
            round::run_compaction_llm(
                llm.as_ref(),
                &old_segment,
                &cancel,
                custom_instruction.as_deref(),
                &hook_additional_context,
                planned_entry_range,
            )
            .await
            .map(|output| {
                // Map the ladder's dropped positions through the old
                // segment's entry numbers (ADR-007 `droppedEntrySeqs`).
                // BY POSITIONS, never by dropped_count: the count includes
                // hook-context slots the translation table skips, and
                // Injection-origin old-segment entries never enter the
                // working copy at all — their numbers surface only in the
                // replaced range, never in this list.
                let dropped_entry_seqs = output
                    .dropped_entry_positions
                    .iter()
                    .map(|&position| old_segment[position].entry_seq)
                    .collect::<Vec<u64>>();
                CompactionResult {
                    summary: output.summary,
                    context_summary: output.context_summary,
                    compacted_count,
                    tokens_before,
                    tokens_after: 0, // Computed in block() after applying.
                    dropped_count: output.dropped_count,
                    dropped_entry_positions: output.dropped_entry_positions,
                    dropped_entry_seqs,
                    applied: false, // Set by the apply path (block/apply_compaction_result).
                    // Filled by the apply path (block/apply_compaction_result).
                    retained_tail_count: 0,
                    kept_head_user_message_count: 0,
                    elision_message: None,
                    first_replaced_entry_seq: None,
                    last_replaced_entry_seq: None,
                }
            })
        });

        self.active = Some(ActiveCompaction {
            cancel: cancel_for_task,
            task,
        });
        // SDR-011: the begin-time history rides with the attempt so the
        // apply seams can run the §5.4 prefix-race check against it.
        self.pending_snapshot = Some(history);
        if matches!(source, CompactionSource::Manual) {
            // The apply task owns the JoinHandle; this token is what a
            // later `cancelCompaction` actuates (the round polls it
            // between attempts, and the apply task checks it before
            // applying so a cancelled attempt never lands in memory).
            // The attempt id scopes every later settle of the
            // registration to the attempt that created it.
            let attempt_id = self.next_manual_attempt_id;
            self.next_manual_attempt_id += 1;
            self.manual_cancel = Some(ManualAttempt {
                id: attempt_id,
                cancel: params.cancel.clone(),
            });
        }
        self.compaction_count_in_turn += 1;

        Ok(())
    }

    /// Wait for an in-flight compaction and apply its result to memory.
    ///
    /// If no compaction is in flight, returns immediately with `Ok(())`.
    ///
    /// This method is async because it awaits the background task.
    ///
    /// **Note**: This method acquires `&mut self` for the entire async
    /// duration. When `self` is behind a `std::sync::Mutex`, use
    /// [`take_active_task`] + [`apply_compaction_result`] instead to avoid
    /// holding the lock across `.await` points.
    ///
    /// [`take_active_task`]: FullCompaction::take_active_task
    /// [`apply_compaction_result`]: FullCompaction::apply_compaction_result
    pub async fn block(
        &mut self,
        memory: &mut ContextMemory,
        cancel: &CancelToken,
    ) -> EngineResult<CompactionResult> {
        // The begin-time snapshot is consumed here (SDR-011): taken before
        // the task await so every exit path — including the cancel branch —
        // clears it.
        let snapshot = self.pending_snapshot.take();
        let mut active = match self.active.take() {
            Some(a) => a,
            None => {
                return Err(EngineError::RequestInvalid(
                    "no active compaction to block on".to_string(),
                ));
            }
        };

        // Wait for the background task, honoring cancellation.
        let mut result = tokio::select! {
            r = &mut active.task => {
                r.map_err(|e| {
                    EngineError::CompactionFailed(format!("compaction task panicked: {}", e))
                })??
            }
            _ = cancel.cancelled() => {
                // Abort the task.
                active.task.abort();
                return Err(EngineError::Aborted(
                    "cancelled while waiting for compaction".to_string(),
                ));
            }
        };

        // §5.4 prefix-race check (SDR-011): while the summarizer ran, only
        // append-only real user input may land — it is re-included by the
        // live re-cut below. Any other divergence (an assistant message, a
        // prefix rewrite, an injection) cancels the round: the summary was
        // computed over a history the live memory no longer matches, and
        // applying it would silently drop the divergent content.
        if let Some(snapshot) = snapshot
            && !round::prefix_race_check(&snapshot, memory.history())
        {
            return Err(EngineError::CompactionFailed(
                "history changed during compaction (prefix-race detected)".to_string(),
            ));
        }

        // Re-cut against the live history: real user input appended during
        // the summarizer call must be re-included in the tail.
        let live_history: Vec<ContextMessage> = memory.history().to_vec();
        let live_cut =
            retention::compute_retention_tail(&live_history, self.retention_budget_tokens());
        let Some(live_cut) = live_cut else {
            // The live history grew into the budget (or no legal cut
            // remains) — applying would compact nothing; report refusal.
            return Ok(CompactionResult {
                applied: false,
                ..result
            });
        };

        // Apply compaction to memory (subject to the shrink check).
        let outcome = memory.apply_compaction(CompactionInput {
            summary: result.summary.clone(),
            context_summary: result.context_summary.clone(),
            compacted_count: live_cut.tail_start as u32,
            tokens_before: result.tokens_before,
            dropped_count: result.dropped_count as u32,
            retention_tail_start: Some(live_cut.tail_start),
        });

        let tokens_after = memory.token_count_with_pending();
        self.last_compacted_token_count = Some(tokens_after);

        // Reset consecutive overflow counter if we've recovered below the
        // recovery ratio.
        let max = self.effective_max_context_tokens();
        if max > 0 && tokens_after < (max as f64 * OVERFLOW_STATUS_RECOVERY_RATIO) as u64 {
            self.consecutive_overflow_compactions = 0;
        }

        result.applied = outcome.applied;
        result.retained_tail_count = outcome.retained_tail_count;
        result.kept_head_user_message_count = outcome.kept_head_user_message_count;
        result.elision_message = outcome.elision_message;
        if outcome.applied {
            // The summarizer snapshot may predate real user input appended
            // during the call — the live re-cut is the prefix length that
            // was actually compacted, and that is what the wire op must
            // persist.
            result.compacted_count = live_cut.tail_start;
            // ADR-007 provenance: the replaced live prefix's entry range,
            // threaded onto the wire op by the apply record's write points.
            let (first, last) = replaced_entry_range(&live_history, live_cut.tail_start);
            result.first_replaced_entry_seq = first;
            result.last_replaced_entry_seq = last;
        }
        result.tokens_after = tokens_after;
        Ok(result)
    }

    /// Take the in-flight compaction task handle out of the orchestrator.
    ///
    /// This is the first half of the `begin`/`block` pattern, designed for use
    /// when `FullCompaction` is behind a `std::sync::Mutex` (so the lock can be
    /// released before awaiting the background task).
    ///
    /// Returns `None` if no compaction is in flight.
    ///
    /// After awaiting the returned `JoinHandle`, call
    /// [`apply_compaction_result`] to apply the result to memory and update
    /// internal state.
    ///
    /// [`apply_compaction_result`]: FullCompaction::apply_compaction_result
    pub fn take_active_task(
        &mut self,
    ) -> Option<tokio::task::JoinHandle<EngineResult<CompactionResult>>> {
        self.active.take().map(|a| a.task)
    }

    /// Take the just-begun manual attempt's task out of the orchestrator,
    /// handing the caller the handle plus the attempt identity its later
    /// settlement must carry.
    pub fn take_manual_task(&mut self) -> Option<ManualCompactionHandle> {
        let task = self.active.take().map(|a| a.task)?;
        let attempt = self.manual_cancel.as_ref()?;
        Some(ManualCompactionHandle {
            task,
            cancel: attempt.cancel.clone(),
            attempt_id: attempt.id,
        })
    }

    /// Whether a manual compaction is in flight (its task handle lives
    /// with the caller's apply task; only the cancel registration
    /// remains here).
    pub fn manual_in_flight(&self) -> bool {
        self.manual_cancel.is_some()
    }

    /// Cancel an in-flight manual compaction. Returns `true` when one was
    /// in flight: the round observes the cancellation between attempts
    /// (and mid-call through the LLM's cancel channel), and the apply task
    /// refuses to apply a cancelled attempt.
    pub fn cancel_manual(&mut self) -> bool {
        match self.manual_cancel.take() {
            Some(attempt) => {
                attempt.cancel.cancel();
                // The cancelled attempt will never apply — its snapshot is
                // dropped along with the registration (SDR-011).
                self.pending_snapshot = None;
                true
            }
            None => false,
        }
    }

    /// Settle a manual attempt: clear its cancel registration only if it
    /// is still the registered attempt — a stale attempt (cancelled and
    /// superseded by a newer begin) must never clear the newer one's
    /// registration, or that newer compaction would become uncancellable
    /// and a further begin would be accepted on top of it.
    pub fn settle_manual(&mut self, attempt_id: u64) {
        if self
            .manual_cancel
            .as_ref()
            .is_some_and(|attempt| attempt.id == attempt_id)
        {
            self.manual_cancel = None;
            // The attempt's snapshot is consumed by its apply seam; on a
            // settle without apply (cancel/error paths), drop it so it can
            // never be mistaken for a later attempt's baseline.
            self.pending_snapshot = None;
            // Wake every turn parked in the buffer phase (see
            // `wait_manual_compaction_settle`); they re-check
            // `manual_in_flight` and proceed once clear.
            self.settle_count += 1;
            let _ = self.settle_tx.send(self.settle_count);
        }
    }

    /// Subscribe to manual-compaction settle signals (see
    /// [`wait_manual_compaction_settle`]).
    pub(crate) fn subscribe_settle(&self) -> tokio::sync::watch::Receiver<u64> {
        self.settle_tx.subscribe()
    }

    /// Apply a completed compaction result to memory and update internal state.
    ///
    /// This is the second half of the `take_active_task`/`apply_compaction_result`
    /// pattern. After awaiting the `JoinHandle` from [`take_active_task`], pass
    /// the result here to apply the compaction summary to memory and update the
    /// `last_compacted_token_count` and `consecutive_overflow_compactions`
    /// counters.
    ///
    /// [`take_active_task`]: FullCompaction::take_active_task
    pub fn apply_compaction_result(
        &mut self,
        memory: &mut ContextMemory,
        result: CompactionResult,
    ) -> CompactionResult {
        // (A manual attempt's cancel registration is settled explicitly
        // by its apply task through `settle_manual`, scoped to its own
        // attempt id — clearing here unconditionally would let a stale
        // attempt wipe a newer one's registration.)
        let mut result = result;

        // §5.4 prefix-race check (SDR-011): the live history must still be
        // the begin-time snapshot plus, at most, appended real user input.
        // Any other divergence cancels the round — the summary was computed
        // over a stale view and applying it would silently drop the
        // divergent content. Mirrors the `block()` seam: memory stays
        // byte-identical, the wire write points only record applied
        // results, so an unapplied return leaves no trace.
        if let Some(snapshot) = self.pending_snapshot.take()
            && !round::prefix_race_check(&snapshot, memory.history())
        {
            return CompactionResult {
                applied: false,
                ..result
            };
        }

        // Re-cut against the live history: real user input appended during
        // the summarizer call must be re-included in the tail.
        let live_history: Vec<ContextMessage> = memory.history().to_vec();
        let live_cut =
            retention::compute_retention_tail(&live_history, self.retention_budget_tokens());
        let Some(live_cut) = live_cut else {
            // The live history grew into the budget (or no legal cut
            // remains) — applying would compact nothing; report refusal.
            return CompactionResult {
                applied: false,
                ..result
            };
        };

        let outcome = memory.apply_compaction(CompactionInput {
            summary: result.summary.clone(),
            context_summary: result.context_summary.clone(),
            compacted_count: live_cut.tail_start as u32,
            tokens_before: result.tokens_before,
            dropped_count: result.dropped_count as u32,
            retention_tail_start: Some(live_cut.tail_start),
        });

        let tokens_after = memory.token_count_with_pending();
        self.last_compacted_token_count = Some(tokens_after);

        // Reset consecutive overflow counter if we've recovered below the
        // recovery ratio.
        let max = self.effective_max_context_tokens();
        if max > 0 && tokens_after < (max as f64 * OVERFLOW_STATUS_RECOVERY_RATIO) as u64 {
            self.consecutive_overflow_compactions = 0;
        }

        result.applied = outcome.applied;
        result.retained_tail_count = outcome.retained_tail_count;
        result.kept_head_user_message_count = outcome.kept_head_user_message_count;
        result.elision_message = outcome.elision_message;
        if outcome.applied {
            // The summarizer snapshot may predate real user input appended
            // during the call — the live re-cut is the prefix length that
            // was actually compacted, and that is what the wire op must
            // persist.
            result.compacted_count = live_cut.tail_start;
            // ADR-007 provenance: the replaced live prefix's entry range,
            // threaded onto the wire op by the apply record's write points.
            let (first, last) = replaced_entry_range(&live_history, live_cut.tail_start);
            result.first_replaced_entry_seq = first;
            result.last_replaced_entry_seq = last;
        }
        result.tokens_after = tokens_after;
        result
    }

    /// Handle an overflow error from the LLM.
    ///
    /// Learns the max context from the estimated token count, increments the
    /// consecutive overflow counter, and returns an error if the limit is
    /// exceeded.
    ///
    /// This method does NOT start a compaction — the caller is responsible
    /// for calling [`begin`] after this returns `Ok(())`.
    ///
    /// [`begin`]: FullCompaction::begin
    pub fn handle_overflow_error(
        &mut self,
        _memory: &ContextMemory,
        _cancel: &CancelToken,
        estimated_tokens: u64,
    ) -> EngineResult<()> {
        self.observe_context_overflow(estimated_tokens);
        self.consecutive_overflow_compactions += 1;

        if self.consecutive_overflow_compactions > self.strategy.max_overflow_compaction_attempts {
            return Err(EngineError::ContextOverflow {
                attempts: self.consecutive_overflow_compactions,
            });
        }

        Ok(())
    }

    /// Whether a background compaction is currently in flight.
    pub fn is_compacting(&self) -> bool {
        self.active.is_some()
    }

    /// Learn the max context from an overflow error.
    ///
    /// The observed max is `estimated_tokens * OVERFLOW_CONTEXT_SAFETY_RATIO`
    /// (rounded down), so we stay safely below the true limit — the failed
    /// request already exceeded the limit, so any value at or above it is
    /// an overestimate. If we've already observed a limit, we keep the
    /// smaller value.
    pub fn observe_context_overflow(&mut self, estimated_tokens: u64) {
        let observed = ((estimated_tokens as f64 * OVERFLOW_CONTEXT_SAFETY_RATIO) as u64).max(1);
        self.observed_max_context_tokens = Some(
            self.observed_max_context_tokens
                .map_or(observed, |existing| existing.min(observed)),
        );
    }

    /// The effective max context tokens: `min(configured, observed)`.
    ///
    /// If neither is known, returns 0.
    pub fn effective_max_context_tokens(&self) -> u64 {
        let configured = self.strategy.max_context_tokens;
        match self.observed_max_context_tokens {
            Some(observed) => {
                if configured == 0 {
                    observed
                } else {
                    configured.min(observed)
                }
            }
            None => configured,
        }
    }

    /// Update the configured max context window (model switch). The
    /// observed-min semantics still apply: `effective_max_context_tokens`
    /// takes the min of this and any overflow-learned value.
    pub fn set_max_context_tokens(&mut self, tokens: u64) {
        self.strategy.max_context_tokens = tokens;
    }

    /// Retention-tail budget (ADR-001): `retention_tail_tokens` when set
    /// (absolute), otherwise window × `retention_tail_ratio` (default 0.16).
    /// When the effective window is unknown (0), the budget is 1 token —
    /// the cut then keeps at least the latest complete indivisible unit
    /// (overflow-recovery semantics).
    pub fn retention_budget_tokens(&self) -> u64 {
        if let Some(tokens) = self.strategy.retention_tail_tokens {
            return tokens.max(1);
        }
        let effective = self.effective_max_context_tokens();
        if effective == 0 {
            return 1;
        }
        ((effective as f64 * self.strategy.retention_tail_ratio) as u64).max(1)
    }

    /// The number of compactions performed in the current turn.
    pub fn compaction_count_in_turn(&self) -> u32 {
        self.compaction_count_in_turn
    }

    /// The consecutive overflow compaction count.
    pub fn consecutive_overflow_compactions(&self) -> u32 {
        self.consecutive_overflow_compactions
    }

    /// The maximum overflow compaction attempts from the strategy.
    pub fn strategy_max_overflow_attempts(&self) -> u32 {
        self.strategy.max_overflow_compaction_attempts
    }

    /// The observed max context tokens (if any).
    pub fn observed_max_context_tokens(&self) -> Option<u64> {
        self.observed_max_context_tokens
    }

    /// Set the compaction count in turn (for testing).
    #[doc(hidden)]
    pub fn set_compaction_count_in_turn_for_test(&mut self, count: u32) {
        self.compaction_count_in_turn = count;
    }
}

// Note: DEFAULT_COMPACTION_MAX_COMPLETION_TOKENS is a private constant used
// internally. Callers that need it can define their own.

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn should_default_max_history_messages_to_10000() {
        assert_eq!(CompactionStrategy::default().max_history_messages, 10_000);
    }

    #[test]
    fn should_default_max_deferred_messages_to_1000() {
        assert_eq!(CompactionStrategy::default().max_deferred_messages, 1_000);
    }
}
